import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [1000, 0],
    [0, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [101], [NaN], [Infinity]])(
      "rejects invalid percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([[0], [50], [100]])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    const policy = new PercentageDiscountPolicy(10);

    it.each([
      [1000, 100],
      [999, 99],
      [1, 0], // floor(0.1) = 0
      [0, 0],
      [-100, 0],
    ])("10%% of %i = %i", (subtotal, expected) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("100% discount returns full subtotal (floored)", () => {
      const full = new PercentageDiscountPolicy(100);
      expect(full.computeDiscountCents(12345)).toBe(12345);
    });

    it("0% discount returns 0", () => {
      const zero = new PercentageDiscountPolicy(0);
      expect(zero.computeDiscountCents(5000)).toBe(0);
    });

    it("rounds down fractional cents", () => {
      const policy = new PercentageDiscountPolicy(33);
      // floor(1000 * 33 / 100) = floor(330) = 330
      expect(policy.computeDiscountCents(1000)).toBe(330);
      // floor(101 * 33 / 100) = floor(33.33) = 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [1.5], [NaN]])(
      "rejects invalid amountCents %s",
      (amount) => {
        expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      },
    );

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    const policy = new FixedAmountDiscountPolicy(500);

    it.each([
      [1000, 500],
      [500, 500],
      [300, 300], // capped at subtotal
      [0, 0],
      [-100, 0],
    ])("fixed 500 on subtotal %i = %i", (subtotal, expected) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums independent discounts on the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed = 200, total = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: floor(1000 * 10 / 100) = 100, remaining = 900
      // Second: floor(900 * 10 / 100) = 90, remaining = 810
      // Total discount = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // A: fixed 500 on 1000 → remaining 500, then 50% of 500 = 250. Total = 750
      // B: 50% of 1000 = 500 → remaining 500, then fixed 500 on 500 = 500. Total = 1000
      expect(policyA.computeDiscountCents(1000)).toBe(750);
      expect(policyB.computeDiscountCents(1000)).toBe(1000);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining = 200
      // Second: min(800, 200) = 200, remaining = 0
      // Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

