  it("clamps negative tax to 0", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("empty cart gives all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses default region US", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(
      expect.any(Number),
      "US",
    );
  });

  it("uses custom region", () => {
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(
      expect.any(Number),
      "FR",
    );
  });
});

describe("Cart.checkout()", () => {
  it("refreshes prices when priceFetcher is provided", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout({ priceFetcher });
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(result.totals.subtotalCents).toBe(1500);
  });

  it("throws InventoryError when item unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    const cart = new Cart();
    cart.add(productA, 2);

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(2);
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    const cart = new Cart();
    cart.add(productA, 3);

    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("succeeds when inventory is sufficient", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart();
    cart.add(productA, 1); // subtotal 1000, no discount → tax on 1000
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(100); // floor(1000 * 0.1)
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines discount + async tax + shipping in checkout", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "FR" });
    cart.add(productA, 2); // subtotal = 2000, discount = 200, taxable = 1800
    const result = await cart.checkout({ asyncTaxProvider });

    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(180); // floor(1800 * 0.1)
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(1800 + 180 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("works with no collaborators (defaults)", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.totalCents).toBe(1000);
  });

  it("checks inventory for all lines sequentially", async () => {
    const calls: string[] = [];
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation((id: string) => {
        calls.push(id);
        return Promise.resolve({ available: true, availableQuantity: 100 });
      }),
    };
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 2);
    await cart.checkout({ inventoryChecker });
    expect(calls).toContain("a");
    expect(calls).toContain("b");
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 1);
    expect(inventoryChecker.check).toHaveBeenCalledWith("b", 2);
  });
});
